export * from './api';
export * from './crypto-js';

import {StripeOnramp, StripeOnrampConstructor} from './crypto-js';
import {
  CryptoOnrampConstructor,
  CryptoOnrampInitOptions,
  OnrampCoordinator,
} from './crypto-js';

export const loadStripeOnramp: (
  publishableKey: string
) => Promise<StripeOnramp | null>;

export const loadCryptoOnrampAndInitialize: (
  publishableKey: string,
  options?: CryptoOnrampInitOptions
) => Promise<OnrampCoordinator | null>;

declare global {
  interface Window {
    // Stripe Onramp must be loaded directly from https://crypto-js.stripe.com, which
    // places a `StripeOnramp` object on the window
    StripeOnramp?: StripeOnrampConstructor;
    // loadCryptoOnrampAndInitialize is loaded from https://js.stripe.com/crypto-onramp/v1/crypto-onramp.js
    loadCryptoOnrampAndInitialize?: CryptoOnrampConstructor;
  }
}
